"""M4 decision cases on P2-P5 (all at the end of Day 12; contracts generated by the funding-advance job).

  P2  45M / 45M  100%  the SME declines (4.3)
  P3  70M / 100M  70%  the SME stays silent: accepted, bound by every contract without signing (4.4); acting after
                       the deadline is refused (4.7); Day 14 in s11
  P4  40M / 100M  40%  the SME signs both contracts and accepts manually below 50% (4.6); the 12:00 cut-off (4.8)
  P5  40M / 100M  40%  the SME stays silent: declined (4.5)
"""
import datetime as dt

import appdb
import builders as B
import e2e_lib as L
from e2e_lib import H, c, err, load, login, record

M = 1_000_000
st = load()
A = H(st["admin"]["token"])
proj = {"P2": st["sme2"]["project"], "P3": st["sme3"]["project"], "P4": st["sme4"]["project"], "P5": st["sme5"]["project"]}
sme = {p: login(st[proj[p]["sme"]]["email"])[0] for p in proj}
tomorrow_15 = dt.datetime.combine(L.ict_today() + dt.timedelta(days=1), dt.time(15, 0), L.ICT)


def win(p):
    return proj[p]["window"]["id"]


def window(cl, p):
    return cl.get(f"/funding/listings/{proj[p]['window']['listing_id']}/window", headers=A).json()


for p in proj:
    deadline = "now() + interval '2 hours'" if p != "P4" else f"timestamptz '{tomorrow_15.isoformat()}'"
    L.psql(f"update funding_windows set commit_closes_at = now() - interval '1 minute', sme_deadline_at = {deadline}, "
           f"pay_deadline_at = {deadline} + interval '23 hours 45 minutes', no_show_at = {deadline} + interval '24 hours', "
           f"receipt_deadline_at = {deadline} + interval '24 hours 30 minutes' where id = '{win(p)}'")
job = appdb.run_job("funding-advance")
print("funding-advance:", job)

with c() as cl:
    # 4.3 P2: Decline
    t0 = L.utcnow_iso()
    r = cl.post(f"/funding/windows/{win('P2')}/decision", json={"decision": "DECLINE"}, headers=H(sme["P2"]) | B.idem())
    w = window(cl, "P2")
    voided = L.psql(f"select string_agg(distinct status, ',') from commitments where window_id = '{win('P2')}'")
    told = L.psql(f"select count(*) from notifications where event = 'WINDOW_DECLINED' and created_at >= '{t0}'")
    fees = [i for i in cl.get("/admin/funding/fee-invoices", headers=A).json() if i["window_id"] == win("P2")]
    record("4.3 Decline: the project ends, every lender is told, no money moved, no fee",
           r.status_code == 200 and w["status"] == "FAILED" and voided == "VOID" and int(told or 0) >= 5 and not fees,
           f"decision {r.status_code}; window {w['status']} / {w['sme_decision']}; pledges {voided}; "
           f"lender notices {told}; fee invoices {len(fees)}")

    # 4.6 + 4.8 P4: below 50%, the SME signs both contracts before 12:00 and accepts
    lc = cl.get(f"/funding/windows/{win('P4')}/loan-contracts", headers=H(sme["P4"])).json()
    cutoff = lc.get("signing_cutoff_at")
    record("4.8 below 50%: the SME is told to finish signing by 12:00 on Day 13",
           cutoff is not None and dt.datetime.fromisoformat(cutoff.replace("Z", "+00:00")).astimezone(L.ICT).time() == dt.time(12, 0),
           f"signing_cutoff_at {cutoff}; deadline {lc.get('sme_deadline_at')}")
    record("4.8 a signature uploaded at or after 12:00 is refused (SIGNING_CUTOFF_PASSED)", "N/A",
           "needs the real clock between 12:00 and 15:00 ICT on Day 13; covered by the backend test "
           "test_below_fifty_percent_signing_closes_at_noon_on_day_13")
signed = appdb.sme_sign_window_contracts(win("P4"), st[proj["P4"]["sme"]]["id"], proj["P4"]["tax"])
with c() as cl:
    r = cl.post(f"/funding/windows/{win('P4')}/decision", json={"decision": "ACCEPT"}, headers=H(sme["P4"]) | B.idem())
    w = window(cl, "P4")
    record("4.6 the SME accepts 40M manually (below 50%): the loan goes ahead at the pledged amount",
           r.status_code == 200 and w["status"] == "AWAITING_PAYMENT" and w["committed_total_vnd"] == 40 * M,
           f"signed {len(signed)} contracts; decision {r.status_code} {err(r)}; window {w['status']} {w['sme_decision']} "
           f"{w['committed_total_vnd']:,}")
    record("6.8 the guarantor's signature is not a condition of acceptance",
           r.status_code == 200 and not cl.get(f"/funding/windows/{win('P4')}/loan-contracts",
                                               headers=H(sme["P4"])).json().get("guarantor_signed_at"),
           "P4 accepted with no guarantor code")

# 4.4 / 4.5: silence at the deadline
for p in ("P3", "P5"):
    L.psql(f"update funding_windows set sme_deadline_at = now() - interval '1 minute', "
           f"pay_deadline_at = now() + interval '3 hours', no_show_at = now() + interval '3 hours 15 minutes', "
           f"receipt_deadline_at = now() + interval '3 hours 45 minutes' where id = '{win(p)}'")
job = appdb.run_job("funding-advance")
with c() as cl:
    w3, w5 = window(cl, "P3"), window(cl, "P5")
    rows3 = cl.get(f"/funding/windows/{win('P3')}/loan-contracts", headers=H(sme["P3"])).json().get("contracts", [])
    record("4.4 silence with 50% or more (70%): accepted; the SME is bound by every contract without signing",
           w3["status"] == "AWAITING_PAYMENT" and w3["sme_decision"] == "AUTO_ACCEPTED"
           and all(r["status"] == "GENERATED" for r in rows3),
           f"job {job}; P3 {w3['status']} / {w3['sme_decision']}; contracts {[r['status'] for r in rows3]}")
    record("4.5 silence below 50% (40%): declined; lenders told; no fee",
           w5["status"] == "FAILED" and w5["sme_decision"] == "AUTO_DECLINED",
           f"P5 {w5['status']} / {w5['sme_decision']}")
    r = cl.post(f"/funding/windows/{win('P3')}/decision", json={"decision": "DECLINE"}, headers=H(sme["P3"]) | B.idem())
    record("4.7 a decision after the deadline is refused", r.status_code == 409, f"{r.status_code} {err(r)}")
